import { type FlexProps } from "@chakra-ui/react";
import React, { forwardRef } from "react";
import {
  type ConversationEvent,
  type ConversationEventAction,
  ConversationEventType,
} from "../../../types";
import { ActionEvent } from "./ActionEvent";
import { AgentEvent } from "./AgentEvent";
import { BotTurnEndedEvent } from "./BotTurnEndedEvent";
import { BargeInEvent } from "./BargeInEvent";
import { TtsFinishedEvent } from "./TtsFinishedEvent";
import { FlowEvent } from "./FlowEvent";
import { LlmCallEvent } from "./LlmCallEvent";
import { MemoryWriteEvent } from "./MemoryWriteEvent";
import { OrderedBlockEvent } from "./OrderedBlockEvent";
import { PlainEvent } from "./PlainEvent";
import { SkillEvent } from "./SkillEvent";
import { SlotEvent } from "./SlotEvent";
import { ToolRunLogRow } from "./ToolRunLogRow";
import { UserInputSuppressedEvent } from "./UserInputSuppressedEvent";
import { UserSilenceTimeoutEvent } from "./UserSilenceTimeoutEvent";

const flowEventTypes = [
  ConversationEventType.FlowCancelled,
  ConversationEventType.FlowCompleted,
  ConversationEventType.FlowStarted,
  ConversationEventType.FlowInterrupted,
  ConversationEventType.FlowResumed,
];
const slotEventTypes = [ConversationEventType.Slot, ConversationEventType.ResetSlots];
const memoryWriteEventTypes = [
  ConversationEventType.MemorySet,
  ConversationEventType.MemoryCleared,
];
const agentEventTypes = [
  ConversationEventType.AgentStarted,
  ConversationEventType.AgentCompleted,
  ConversationEventType.AgentCancelled,
  ConversationEventType.AgentInterrupted,
  ConversationEventType.AgentResumed,
];
const skillEventTypes = [
  ConversationEventType.SkillActivated,
  ConversationEventType.SkillCompleted,
  ConversationEventType.SkillCancelled,
  ConversationEventType.SkillInterrupted,
  ConversationEventType.SkillResumed,
];
const orderedBlockEventTypes = [
  ConversationEventType.OrderedBlockEntered,
  ConversationEventType.OrderedBlockCompleted,
  ConversationEventType.OrderedBlockCancelled,
  ConversationEventType.OrderedBlockInterrupted,
  ConversationEventType.OrderedBlockResumed,
];

interface EventRowProps {
  event: ConversationEvent;
  isSelected: boolean;
  conversationEventActions?: ConversationEventAction[];
  onClick?: React.MouseEventHandler<HTMLDivElement>;
  onKeyDown?: (e: React.KeyboardEvent<HTMLDivElement>) => void;
}

type EventRowComponent = React.ForwardRefExoticComponent<
  EventRowProps & React.RefAttributes<HTMLDivElement | null>
>;

function rowEntries(
  eventTypes: readonly ConversationEventType[],
  component: EventRowComponent,
): [ConversationEventType, EventRowComponent][] {
  return eventTypes.map((eventType) => [eventType, component]);
}

/** Event types whose row differs only in which component renders it. */
const uniformRowComponents = new Map<ConversationEventType, EventRowComponent>([
  ...rowEntries(flowEventTypes, FlowEvent),
  ...rowEntries(slotEventTypes, SlotEvent),
  ...rowEntries(memoryWriteEventTypes, MemoryWriteEvent),
  ...rowEntries(agentEventTypes, AgentEvent),
  ...rowEntries(skillEventTypes, SkillEvent),
  ...rowEntries(orderedBlockEventTypes, OrderedBlockEvent),
  [ConversationEventType.BotTurnEnded, BotTurnEndedEvent],
  [ConversationEventType.TtsFinished, TtsFinishedEvent],
  [ConversationEventType.UserBargeIn, BargeInEvent],
  [ConversationEventType.UserInputSuppressed, UserInputSuppressedEvent],
  [ConversationEventType.UserSilenceTimeout, UserSilenceTimeoutEvent],
]);

interface Props extends FlexProps {
  event: ConversationEvent;
  selectable?: boolean;
  isSelected?: boolean;
  onEventSelect?: (selection: ConversationEvent) => void;
  replayConversation?: (eventId: string) => void;
  isLastActiveEvent?: boolean;
  conversationEventActions?: ConversationEventAction[];
  /** Tool-call rows heading a group: expansion state for the chevron. */
  toolCallExpanded?: boolean;
  onToolCallToggle?: () => void;
  /** LLM-call rows heading a group: expansion state for the chevron. */
  llmCallExpanded?: boolean;
  onLlmCallToggle?: () => void;
}

export const Event = forwardRef<HTMLDivElement | null, Props>((props: Props, ref) => {
  const {
    event,
    selectable = false,
    onEventSelect,
    isSelected = false,
    replayConversation,
    isLastActiveEvent = false,
    toolCallExpanded,
    onToolCallToggle,
    llmCallExpanded,
    onLlmCallToggle,
    ...otherProps
  } = props;
  const handleSelect = () => {
    if (selectable && onEventSelect) {
      onEventSelect(event);
    }
  };

  const additionalProps = {
    ...otherProps,
    "data-testid": isLastActiveEvent
      ? "conversation-events-last-active-event"
      : "conversation-events",
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Enter" && selectable && onEventSelect) {
      onEventSelect(event);
    }
  };

  const UniformRow = uniformRowComponents.get(event.conversationEventType);
  if (UniformRow) {
    return (
      <UniformRow
        ref={ref}
        event={event}
        onClick={handleSelect}
        onKeyDown={handleKeyDown}
        isSelected={selectable && isSelected}
        {...additionalProps}
      />
    );
  }

  if (event.conversationEventType === ConversationEventType.Action) {
    return (
      <ActionEvent
        ref={ref}
        event={event}
        onClick={handleSelect}
        onKeyDown={handleKeyDown}
        isSelected={selectable && isSelected}
        replayConversation={replayConversation}
        {...additionalProps}
      />
    );
  }

  if (
    event.conversationEventType === ConversationEventType.ToolExecuted ||
    event.conversationEventType === ConversationEventType.McpToolExecuted
  ) {
    const isMantleTool = event.conversationEventType === ConversationEventType.ToolExecuted;
    return (
      <ToolRunLogRow
        ref={ref}
        event={event}
        onClick={handleSelect}
        onKeyDown={handleKeyDown}
        isSelected={selectable && isSelected}
        expanded={toolCallExpanded}
        onToggleExpand={onToolCallToggle}
        prefix={isMantleTool ? "Tool call: " : "Tool "}
        suffix={isMantleTool ? "" : " used"}
        {...additionalProps}
      />
    );
  }

  if (event.conversationEventType === ConversationEventType.LlmCallRecorded) {
    return (
      <LlmCallEvent
        ref={ref}
        event={event}
        onClick={handleSelect}
        onKeyDown={handleKeyDown}
        isSelected={selectable && isSelected}
        expanded={llmCallExpanded}
        onToggleExpand={onLlmCallToggle}
        {...additionalProps}
      />
    );
  }

  return (
    <PlainEvent
      ref={ref}
      event={event}
      onClick={handleSelect}
      onKeyDown={handleKeyDown}
      isSelected={selectable && isSelected}
      {...additionalProps}
    />
  );
});
